interface MasterSpecFieldsControlProps {
  specJson: string;
  primaryShadowTable?: string | null;
  disabled?: boolean;
  onChangeSpecJson: (nextSpecJson: string) => void;
}

export const MasterSpecFieldsControl: React.FC<MasterSpecFieldsControlProps> = ({
  specJson,
  primaryShadowTable,
  disabled,
  onChangeSpecJson,
}) => {
  const currentTimestampField = React.useMemo(() => {
    try {
      const parsed = specJson.trim() ? JSON.parse(specJson) : {};
      return typeof parsed?.timestamp_field === 'string' ? parsed.timestamp_field : '';
    } catch {
      return '';
    }
  }, [specJson]);

  const handleTimestampFieldChange = (val: string) => {
    let parsed: Record<string, any> = {};
    try {
      const obj = specJson.trim() ? JSON.parse(specJson) : {};
      if (obj && typeof obj === 'object' && !Array.isArray(obj)) parsed = obj;
    } catch {
      parsed = {};
    }
    const trimmed = val.trim();
    if (trimmed) {
      parsed.timestamp_field = trimmed;
    } else {
      delete parsed.timestamp_field;
    }
    if (Array.isArray(parsed.shadow_sources) && primaryShadowTable) {
      parsed.shadow_sources = parsed.shadow_sources.map((s: any) =>
        s && s.shadow_table === primaryShadowTable
          ? { ...s, timestamp_field: trimmed || undefined }
          : s,
      );
    }
    onChangeSpecJson(JSON.stringify(parsed));
  };

  return (
    <div>
      <Text strong style={{ display: 'block', marginBottom: 4 }}>
        Timestamp Field
      </Text>
      <Input
        placeholder="Tự động lấy từ Shadow (vd: updated_at, updatedAt, lastUpdatedAt) hoặc nhập tên trường trên Master"
        disabled={disabled}
        value={currentTimestampField}
        onChange={(e) => handleTimestampFieldChange(e.target.value)}
      />
    </div>
  );
};

