	var rawFields []string
	if primaryTS := g.resolveMasterTimestampField(ctx, reg); primaryTS != "" {
		rawFields = append(rawFields, primaryTS)
	}
	if reg != nil && len(reg.TransformSpec) > 0 {
		if sources, err := transmute.ParseShadowSources(reg.TransformSpec); err == nil {
			for _, s := range sources {
				if ts := strings.TrimSpace(s.TimestampField); ts != "" {
					rawFields = append(rawFields, ts)
				}
			}
		}
	}
	var out []string
	for _, f := range rawFields {
		trimmed := strings.TrimSpace(f)
		if trimmed == "" {
			continue
		}
		if !strings.HasPrefix(trimmed, "_") && strings.Contains(trimmed, "_") {
			if camel := snakeToCamelKey(trimmed); camel != "" {
				out = append(out, camel)
			}
		} else {
			out = append(out, trimmed)
		}
	}
	return out
}

func snakeToCamelKey(s string) string {
	parts := strings.Split(s, "_")
	if len(parts) <= 1 {
		return s

