func (t *TransmuterModule) handleEventDelete(
	ctx context.Context,
	masterRow *masterBindingRuntime,
	colTypes map[string]string,
	sourceID string,
	deletedInBatch map[string]bool,
	res *TransmuteResult,
	lastEventErr *error,
) {
	if sourceID != "" && deletedInBatch[sourceID] {
		res.Skipped++
		if t.logger != nil {
			t.logger.Info("transmuter: duplicate delete event in same batch skipped (multi-shadow 1:1 peer)",
				zap.String("master", masterRow.MasterTable),
				zap.String("source_id", sourceID))
		}
		return
	}
	delCnt, delErr := t.deleteFromMasterBySourceAndGpayIDs(ctx, masterRow, colTypes, []string{sourceID}, nil)
	if delErr != nil {
		if t.logger != nil {
			t.logger.Error("transmuter: event delete master failed",
				zap.String("master", masterRow.MasterTable),
				zap.String("source_id", sourceID),
				zap.Error(delErr))
		}
		res.Skipped++
		if *lastEventErr == nil {
			*lastEventErr = delErr
		}
		return
	}
	if delCnt > 0 {
		if sourceID != "" {
			deletedInBatch[sourceID] = true
		}
		res.Deleted += delCnt
		res.Written += delCnt
		return
	}
	if masterRow != nil && masterRow.TransformType == "multi_shadow" {
		if sourceID != "" {
			deletedInBatch[sourceID] = true
		}
		res.Skipped++
		if t.logger != nil {
			t.logger.Info("transmuter: delete event skipped (already deleted on master by multi-shadow 1:1 peer)",
				zap.String("master", masterRow.MasterTable),
				zap.String("source_id", sourceID))
		}
		return
	}
	res.Deleted++
	res.Written += delCnt
}

